import express from "express";
import { fileURLToPath } from "node:url";
import {
  connectDB,
  getAllStudents,
  findStudentsByDept,
  findStudentsByMinMarks,
  getTopThreeStudents,
  addStudent,
} from "./database.js";

const app = express();
const PORT = 3000;

app.use(express.json());
app.use(express.static(fileURLToPath(new URL("./public", import.meta.url))));

function sendList(res, data, functionName) {
  if (!Array.isArray(data)) {
    return res.status(500).json({
      error: `${functionName}() did not return a list from the database. Complete it in database.js.`,
    });
  }
  res.json(data);
}

app.get("/api/students", async (req, res) => {
  try {
    sendList(res, await getAllStudents(), "getAllStudents");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/students/search", async (req, res) => {
  try {
    sendList(res, await findStudentsByDept(req.query.dept), "findStudentsByDept");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/students/filter", async (req, res) => {
  const minMarks = Number(req.query.minMarks);
  if (Number.isNaN(minMarks)) {
    return res.status(400).json({ error: "Please enter a number." });
  }
  try {
    sendList(res, await findStudentsByMinMarks(minMarks), "findStudentsByMinMarks");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get("/api/students/top", async (req, res) => {
  try {
    sendList(res, await getTopThreeStudents(), "getTopThreeStudents");
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post("/api/students", async (req, res) => {
  try {
    const saved = await addStudent(req.body);
    if (!saved) {
      return res.status(500).json({
        error: "addStudent() did not return the saved student. Complete it in database.js.",
      });
    }
    res.status(201).json(saved);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

try {
  await connectDB();
} catch (err) {
  console.log("Could not connect to MongoDB:", err.message);
}

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
